"use strict";

(function () {
    const storageKey = "user-color-scheme";
    const validThemes = new Set(["light", "dark"]);
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");

    function readStoredTheme() {
        try {
            const value = localStorage.getItem(storageKey);
            return validThemes.has(value) ? value : null;
        } catch (_error) {
            return null;
        }
    }

    function writeStoredTheme(theme) {
        try {
            localStorage.setItem(storageKey, theme);
        } catch (_error) {
            // Theme switching still works for this page when storage is unavailable.
        }
    }

    function preferredTheme() {
        return mediaQuery.matches ? "dark" : "light";
    }

    function applyTheme(theme) {
        const effectiveTheme = validThemes.has(theme) ? theme : preferredTheme();
        const stylesheet = document.getElementById("darkmode-css");

        document.documentElement.setAttribute("data-theme", effectiveTheme);

        if (stylesheet) {
            stylesheet.media = "all";
            stylesheet.disabled = effectiveTheme !== "dark";
        }
    }

    function toggleTheme() {
        const currentTheme =
            document.documentElement.getAttribute("data-theme") || preferredTheme();
        const nextTheme = currentTheme === "dark" ? "light" : "dark";

        writeStoredTheme(nextTheme);
        applyTheme(nextTheme);
    }

    applyTheme(readStoredTheme());

    // Event delegation keeps the switch working after PJAX replaces page content.
    document.addEventListener("click", function (event) {
        const switchButton = event.target.closest("#darkmode-switch");
        if (!switchButton) return;

        event.preventDefault();
        toggleTheme();
    });

    const handleSystemThemeChange = function () {
        if (!readStoredTheme()) applyTheme(null);
    };

    if (typeof mediaQuery.addEventListener === "function") {
        mediaQuery.addEventListener("change", handleSystemThemeChange);
    } else if (typeof mediaQuery.addListener === "function") {
        mediaQuery.addListener(handleSystemThemeChange);
    }
})();
